  const [message, setMessage] = useState('');

  const handleSend = async () => {
    if (!recipient || !message) {
      Alert.alert('Erro', 'Preencha todos os campos.');
      return;
    }

    try {
      const response = await fetch('https://seu-servidor.com/api/send-anonymous', {
