const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// Configuração do motor de visualização
app.set('view engine', 'ejs');
app.use(express.urlencoded({ extended: true }));
app.use(express.static('public'));

// Banco de dados simulado (em produção, usar PostgreSQL ou MongoDB)
let contents = [
    { id: 1, title: 'Filme Exemplo 1', magnet: 'magnet:?xt=urn:btih:exemplo1...' },
    { id: 2, title: 'Série Exemplo 2', magnet: 'magnet:?xt=urn:btih:exemplo2...' }
];

// Rota principal
app.get('/', (req, res) => {
    res.render('index', { contents });
});

// Rota para adicionar conteúdo (simulada)
app.post('/add', (req, res) => {
    const { title, magnet } = req.body;
    contents.push({ id: contents.length + 1, title, magnet });
    res.redirect('/');
});

app.listen(PORT, () => {
    console.log(`Servidor rodando na porta ${PORT}`);
});
```

**Interface do Usuário (`views/index.ejs`):**
```html
