    <h2>Adicionar Link</h2>
    <form action="/add" method="POST">
        <input type="text" name="title" placeholder="Título" required>
        <input type="text" name="magnet" placeholder="Link Magnet / URL" required>
        <button type="submit">Enviar</button>
    </form>

    <h2>Disponíveis</h2>
