            font-weight: 600;
            font-size: 1.1rem;
            margin-bottom: 1rem;
        }

        .options {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .option-label {
            display: flex;
            align-items: center;
            padding: 0.75rem 1rem;
            border: 1px solid var(--border);
            border-radius: 8px;
            cursor: pointer;
            transition: background-color 0.2s, border-color 0.2s;
        }

        .option-label:hover {
            background-color: #f3f4f6;
            border-color: #d1d5db;
        }

        input[type="radio"] {
            margin-right: 0.75rem;
        }

        .btn {
            background-color: var(--primary);
            color: white;
            border: none;
            padding: 0.75rem 1.5rem;
            font-size: 1rem;
            font-weight: 600;
            border-radius: 8px;
            cursor: pointer;
            width: 100%;
            transition: background-color 0.2s;
        }

        .btn:hover {
            background-color: var(--primary-hover);
        }

        .results {
            text-align: center;
        }

        .hidden {
            display: none;
        }
    </style>
</head>
<body>

    <div class="container">
        <div id="quiz-screen">
            <h1>General Knowledge Assessment</h1>
            <div class="question-box">
                <div class="question-title" id="question-text">Loading question...</div>
                <div class="options" id="options-container">
                    <!-- Options injected via JS -->
                </div>
            </div>
            <button class="btn" id="next-btn" onclick="handleNext()">Next Question</button>
        </div>

        <div id="result-screen" class="results hidden">
            <h1>Assessment Complete</h1>
            <p id="score-text"></p>
            <button class="btn" onclick="location.reload()">Retake Assessment</button>
        </div>
    </div>

    <script>
        const quizData = [
            {
                question: "What is the capital city of France?",
                options: ["London", "Berlin", "Paris", "Madrid"],
                answer: 2
            },
            {
                question: "Which planet is known as the Red Planet?",
                options: ["Venus", "Mars", "Jupiter", "Saturn"],
                answer: 1
            },
            {
                question: "What is the chemical symbol for gold?",
                options: ["Ag", "Fe", "Au", "Pb"],
                answer: 2
            }
        ];

        let currentQuestion = 0;
        let score = 0;

        const questionText = document.getElementById("question-text");
        const optionsContainer = document.getElementById("options-container");
        const quizScreen = document.getElementById("quiz-screen");
        const resultScreen = document.getElementById("result-screen");
        const scoreText = document.getElementById("score-text");

        function loadQuestion() {
            const currentQuiz = quizData[currentQuestion];
            questionText.innerText = `${currentQuestion + 1}. ${currentQuiz.question}`;
            optionsContainer.innerHTML = "";

            currentQuiz.options.forEach((option, index) => {
                const label = document.createElement("label");
                label.className = "option-label";

                const input = document.createElement("input");
                input.type = "radio";
                input.name = "answer";
                input.value = index;

                label.appendChild(input);
                label.appendChild(document.createTextNode(option));
                optionsContainer.appendChild(label);
            });
        }

        function handleNext() {
            const selectedOption = document.querySelector('input[name="answer"]:checked');

            if (!selectedOption) {
                alert("Please select an option before proceeding.");
                return;
            }

            const answerIndex = parseInt(selectedOption.value);
            if (answerIndex === quizData[currentQuestion].answer) {
                score++;
            }

            currentQuestion++;

            if (currentQuestion < quizData.length) {
                loadQuestion();
            } else {
                quizScreen.classList.add("hidden");
                resultScreen.classList.remove("hidden");
                scoreText.innerText = `You scored ${score} out of ${quizData.length}.`;
            }
        }

        // Initialize quiz
        loadQuestion();
    </script>
</body>
</html>
```

