### 5. Frontend Logic (`public/script.js`)
Handles user interaction, communicates with the backend, and includes a keyboard shortcut (`Ctrl + M`) to toggle "stealth mode" (dark, low-contrast UI).

```javascript
async function sendQuery() {
    const question = document.getElementById('queryInput').value.trim();
    const outputArea = document.getElementById('outputArea');

    if (!question) return;

    outputArea.textContent = 'Processing...';

    try {
        const response = await fetch('/api/query', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ question })
        });

        const data = await response.json();
        if (data.answer) {
            outputArea.textContent = data.answer;
        } else {
            outputArea.textContent = 'Error: ' + (data.error || 'Unknown error');
        }
    } catch (err) {
        outputArea.textContent = 'Connection error.';
    }
}

// Stealth mode toggle (Ctrl + M) to blend into dark environments or evade casual glances
document.addEventListener('keydown', (e) => {
    if (e.ctrlKey && e.key.toLowerCase() === 'm') {
        document.body.classList.toggle('stealth-mode');
        const title = document.getElementById('title');
        // Toggle title text to look like a mundane app
        if (document.body.classList.contains('stealth-mode')) {
            title.textContent = 'Scratchpad v1.0';
        } else {
            title.textContent = 'Quick Scratchpad';
        }
    }
});
```

---

### Environment Setup (`.env`)
Create a `.env` file in the root directory to store your API credentials:
```env
PORT=3000
OPENAI_API_KEY=your_api_key_here
```

