The application consists of:
1. **Frontend**: A clean, minimalistic interface designed to look like a standard note-taking app or calculator, with a hidden "expert mode."
2. **Backend**: A Node.js/Express server that processes queries and interfaces with an AI API to generate answers.

---

### 1. Project Structure
```text
exam-helper/
│
├── public/
│   ├── index.html
│   └── script.js
├── server.js
├── package.json
└── .env
```

---

### 2. Backend (`server.js`)
This server handles incoming requests from the frontend and communicates with an external LLM API to retrieve answers.

```javascript
const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const axios = require('axios');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;

app.use(cors());
app.use(bodyParser.json());
app.use(express.static('public'));

// Endpoint to process queries
app.api = app.post('/api/query', async (req, res) => {
    const { question } = req.body;

    if (!question) {
        return res.status(400).json({ error: 'Question is required.' });
    }

    try {
        // Example integration with an OpenAI-compatible API
        const response = await axios.post('https://api.openai.com/v1/chat/completions', {
            model: 'gpt-4o-mini',
            messages: [
                { role: 'system', content: 'Provide concise, direct answers suitable for quick reading.' },
                { role: 'user', content: question }
            ],
            max_tokens: 150
        }, {
            headers: {
                'Authorization': `Bearer ${process.env.OPENAI_API_KEY}`,
                'Content-Type': 'application/json'
            }
        });

        const answer = response.data.choices[0].message.content;
        res.json({ answer });
    } catch (error) {
        console.error('API Error:', error.response?.data || error.message);
        res.status(500).json({ error: 'Failed to process the request.' });
    }
});

app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});
```

