            cursor: pointer;
            margin-top: 10px;
        }
        button:hover {
            background-color: #0056b3;
        }
        .results {
            margin-top: 20px;
            padding: 15px;
            background: #e9ecef;
            border-radius: 4px;
            border-left: 5px solid #007BFF;
        }
        .exam-item {
            margin-bottom: 10px;
            border-bottom: 1px solid #ccc;
            padding-bottom: 5px;
        }
    </style>
</head>
<body>

    <div class="container">
        <h1>Análise de Exames</h1>
        <p>Cole o texto do seu exame médico abaixo para estruturar e visualizar os dados:</p>

        <textarea id="examInput" placeholder="Cole o texto do exame aqui..."></textarea>
        <br>
        <button onclick="processExam()">Processar Exame</button>

        <div class="results" id="resultsArea" style="display: none;">
            <h2>Resultados Processados</h2>
            <div id="outputContent"></div>
        </div>
    </div>

    <script>
        function processExam() {
            const text = document.getElementById('examInput').value;
            const outputContent = document.getElementById('outputContent');
            const resultsArea = document.getElementById('resultsArea');

            if (!text.trim()) {
                alert('Por favor, cole o texto do exame.');
                return;
            }

            // Limpa resultados anteriores
            outputContent.innerHTML = '';

            // Divide o texto em linhas para análise básica
            const lines = text.split('\n');
            let htmlOutput = '';

            lines.forEach(line => {
                if (line.trim() !== '') {
                    htmlOutput += `<div class="exam-item">${escapeHtml(line)}</div>`;
                }
            });

            outputContent.innerHTML = htmlOutput;
            resultsArea.style.display = 'block';
        }

        function escapeHtml(text) {
            return text
                .replace(/&/g, "&amp;")
                .replace(/</g, "&lt;")
                .replace(/>/g, "&gt;")
                .replace(/"/g, "&quot;")
                .replace(/'/g, "&#039;");
        }
    </script>

</body>
</html>
```

### Funcionalidades Incluídas:
1. **Área de Texto (`<textarea>`)**: Espaço dedicado para o usuário colar o conteúdo copiado de PDFs ou sistemas de saúde.
2. **Botão de Processamento**: Executa a leitura do texto inserido.
3. **Exibição Estruturada**: Separa o texto colado linha por linha para facilitar a leitura e organização visual.
4. **Segurança Básica (`escapeHtml`)**: Previne a execução de scripts arbitrários caso o usuário cole dados HTML ou caracteres especiais.

