   ```javascript
   // PersonaSelector.js
   import React from 'react';
   import { View, Button } from 'react-native';

   export default function PersonaSelector({ onSelect }) {
     return (
       <View>
         <Button title="Selecionar Persona 🎭" onPress={() => onSelect('provocation_profile')} />
       </View>
     );
   }
   ```

