       const response = await axios.post(endpoint, {
         message: payload.text,
         target: payload.recipient,
         mode: 'unrestricted'
       });
       return response.data;
     } catch (error) {
       console.error("Erro no envio 📤💬:", error);
     }
   };
   ```

